const records = window.MODEL_ATLAS_DATA.records;
const labels={free:'有免费档',trial:'新人 / 限时试用',unknown:'付费 / 待确认'};
let favorites=[];try{favorites=JSON.parse(localStorage.getItem('model-atlas-favorites')||'[]');if(!Array.isArray(favorites))favorites=[]}catch{}
const state={q:'',purpose:'全部',type:'all',onlyFav:false};
const $=id=>document.getElementById(id);
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function matches(r){const text=[r.name,r.provider,r.id||'',...r.uses,r.note].join(' ').toLowerCase();return(!state.q||text.includes(state.q.toLowerCase()))&&(state.purpose==='全部'||r.uses.includes(state.purpose))&&(state.type==='all'||r.type===state.type)&&(!state.onlyFav||favorites.includes(r.key))}
function render(){const items=records.filter(matches);$('count').textContent=`${items.length} 个结果 · 共 ${records.length} 条模型 / 平台记录`;$('empty').hidden=items.length>0;$('cards').innerHTML=items.map(r=>`<article class="card"><div class="card-head"><span class="monogram">${escapeHtml(r.provider.slice(0,1))}</span><button class="save" data-save="${r.key}" aria-label="${favorites.includes(r.key)?'取消收藏':'收藏'} ${escapeHtml(r.name)}" aria-pressed="${favorites.includes(r.key)}">${favorites.includes(r.key)?'★':'☆'}</button></div><div class="provider">${escapeHtml(r.provider)}</div><h2>${escapeHtml(r.name)}</h2><span class="badge ${r.type}">${labels[r.type]}</span><div class="quota">${escapeHtml(r.quota)}</div><p class="note">${escapeHtml(r.note)}</p><div class="tags">${r.uses.map(u=>`<span>${u}</span>`).join('')}</div><div class="actions"><button class="primary" data-detail="${r.key}">查看条件 ↗</button>${r.id?`<button class="secondary" data-copy="${r.key}">复制 ID</button>`:`<a class="secondary" href="${r.source}" target="_blank" rel="noopener noreferrer">官方入口 ↗</a>`}</div></article>`).join('')}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
async function copyId(r){try{await navigator.clipboard.writeText(r.id);toast('已复制模型 ID')}catch{openDetail(r);toast('无法自动复制，请在详情中选中模型 ID 复制')}}
function openDetail(r){$('detailContent').innerHTML=`<span class="badge ${r.type}">${labels[r.type]}</span><h2>${escapeHtml(r.name)}</h2>${r.id?`<div class="detail-id"><code>${escapeHtml(r.id)}</code><button class="secondary" data-copy="${r.key}">复制 ID</button></div>`:'<p class="small">这是平台 / 厂商入口，请在官方目录选择具体模型。</p>'}<dl><dt>额度与速率限制</dt><dd>${escapeHtml(r.limits)}</dd><dt>有效期</dt><dd>${escapeHtml(r.expiry)}</dd><dt>账号、地区与使用条件</dt><dd>${escapeHtml(r.conditions)}</dd><dt>数据与许可证</dt><dd>${escapeHtml(r.data)}</dd><dt>核查日期</dt><dd>${escapeHtml(r.checkedAt)} · 公开资料来源复核；非实时，未确认条件仍需另查</dd><dt>官方来源</dt><dd><a href="${r.source}" target="_blank" rel="noopener noreferrer">${r.source}</a></dd></dl>`;if(!$('detail').open)$('detail').showModal()}
function reset(){Object.assign(state,{q:'',purpose:'全部',type:'all',onlyFav:false});$('search').value='';$('type').value='all';$('onlyFav').checked=false;document.querySelectorAll('[data-purpose]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.purpose==='全部'));render()}
$('purposes').innerHTML=['全部','编程','写作','翻译','图片理解'].map((p,i)=>`<button class="pill" data-purpose="${p}" aria-pressed="${!i}">${p}</button>`).join('');
$('search').addEventListener('input',e=>{state.q=e.target.value.trim();render()});$('type').addEventListener('change',e=>{state.type=e.target.value;render()});$('onlyFav').addEventListener('change',e=>{state.onlyFav=e.target.checked;render()});$('reset').onclick=reset;$('emptyReset').onclick=reset;$('close').onclick=()=>$('detail').close();
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.purpose){state.purpose=b.dataset.purpose;document.querySelectorAll('[data-purpose]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.save){const k=b.dataset.save;favorites=favorites.includes(k)?favorites.filter(x=>x!==k):[...favorites,k];try{localStorage.setItem('model-atlas-favorites',JSON.stringify(favorites))}catch{toast('本次打开期间已收藏，浏览器未允许持久保存')}render()}if(b.dataset.detail)openDetail(records.find(r=>r.key===b.dataset.detail));if(b.dataset.copy)copyId(records.find(r=>r.key===b.dataset.copy))});
const checkedDates = [...new Set(records.map(r=>r.checkedAt))].sort();
$('catalogDate').textContent = checkedDates.length === 1 ? checkedDates[0].replaceAll('-', '.') : checkedDates[0].replaceAll('-', '.') + ' — ' + checkedDates[checkedDates.length-1].replaceAll('-', '.');
render();
